mapper.delete:
delete from u_s_pageview
 where createtime < #{before}
 order by id
 limit #{limit}

mapper.update:
update u_s_pv_daily d
  join (select pagetype, goodscode, count(distinct visitorid) uv
          from u_s_pageview
         where sitecode = #{siteCode}
           and isbot = 0
           and createtime >= #{from}
           and createtime < #{to}
         group by pagetype, goodscode) s
    on s.pagetype  = d.pagetype
   and s.goodscode = d.goodscode
   set d.uv = s.uv
 where d.sitecode = #{siteCode}
   and d.statdate = #{statDate}
   and d.pagetype <> '_all'

update u_s_pv_daily
   set uv = (select count(distinct visitorid)
               from u_s_pageview
              where sitecode = #{siteCode}
                and isbot = 0
                and createtime >= #{from}
                and createtime < #{to})
 where sitecode  = #{siteCode}
   and statdate  = #{statDate}
   and pagetype  = '_all'
   and goodscode = ''

mapper.select:
select statdate, pv, pvhuman, uv
  from u_s_pv_daily
 where sitecode = #{siteCode}
   and pagetype = '_all'
   and statdate >= #{fromDate}
   and statdate <= #{toDate}
 order by statdate

select count(distinct visitorid)
  from u_s_pageview
 where sitecode = #{siteCode}
   and isbot = 0
   and createtime >= #{from}
   and createtime < #{to}

select statdate, pv, pvhuman, uv
  from u_s_pv_daily
 where sitecode  = #{siteCode}
   and statdate  = #{statDate}
   and pagetype  = '_all'
   and goodscode = ''

select v.goodscode, g.goodsname, g.spec, g.price, g.moq, g.unit, g.publishstatus, g.sitecategory, v.pv, ifnull(u.uv, 0) uv, ifnull(i.cnt, 0) inquirycount, ifnull(o.cnt, 0) ordercount from (select goodscode, sum(pvhuman) pv from u_s_pv_daily where sitecode = #{siteCode} and pagetype = 'detail' and goodscode <> '' and statdate >= #{fromDate} group by goodscode having sum(pvhuman) > 0) v
left join u_s_sitegoods g on g.goodscode = v.goodscode and g.sitecode = #{siteCode}
left join (select goodscode, count(distinct visitorid) uv from u_s_pageview where sitecode = #{siteCode} and isbot = 0 and goodscode <> '' and createtime >= #{fromTime} group by goodscode) u on u.goodscode = v.goodscode
left join (select goodscode, count(*) cnt from u_s_inquiry where goodscode is not null and goodscode <> '' and createtime >= #{fromTime} group by goodscode) i on i.goodscode = v.goodscode
left join (select oi.goodscode, count(distinct oi.ordercode) cnt from u_s_orderitem oi join u_s_order o2 on o2.ordercode = oi.ordercode where o2.createtime >= #{fromTime} and o2.status <> '已取消' group by oi.goodscode) o on o.goodscode = v.goodscode order by v.pv desc limit #{limit}

select case
         when referrer is null or referrer = '' then '(direct)'
         else substring_index(substring_index(referrer, '/', 3), '//', -1)
       end      host,
       count(*) pv,
       count(distinct visitorid) uv
  from u_s_pageview
 where sitecode = #{siteCode}
   and isbot = 0
   and createtime >= #{from}
 group by host
 order by pv desc
 limit #{limit}
